fn persona(agent: &str) -> (&'static str, &'static str, &'static str) {
    AGENT_PERSONAS
        .iter()
        .find(|(n, _, _)| *n == agent)
        .copied()
        .unwrap_or_else(|| AGENT_PERSONAS[0])
}

fn friendly_name(agent: &str) -> String {
    if agent.trim().is_empty() {
        "Archi".to_string()
    } else {
        agent.trim().to_string()
    }
}

/// Fill {agent}/{title}/{style} in a greeting template.
fn fill(template: &str, agent: &str, title: &str, style: &str) -> String {
    template
        .replace("{agent}", agent)
        .replace("{title}", title)
        .replace("{style}", style)
}

/// Parse arithmetic "A <op> B" with optional space, and with/without a leading
/// "what is"/"calculate"/"compute" phrase. Mirrors the Python TIER 2 regex but
/// also catches bare "2+2" and "2 + 2" so a trivial query never falls through to
/// the 7s generation path.
fn try_math(msg: &str) -> Option<String> {
    let lower = msg.trim().to_lowercase();
    let expr = ["what is ", "what's ", "calculate ", "compute ", "evaluate ", "what is the result of "]
        .iter()
        .find_map(|p| lower.strip_prefix(p))
        .unwrap_or(&lower)
        .trim();
    // First operator char (+ - * / × ÷) that is not a leading sign on the first operand.
    let start = if expr.starts_with('-') { 1 } else { 0 };
    let (op_idx, op_ch) = expr.char_indices().skip(start)
        .find(|(_, c)| "+-*/×÷".contains(*c))?;
    let a: f64 = expr[..op_idx].trim().parse().ok()?;
    let b: f64 = expr[op_idx + op_ch.len_utf8()..].trim().parse().ok()?;
    let a_i = a as i64;
    let b_i = b as i64;
    let int_in = a.fract() == 0.0 && b.fract() == 0.0;
    let out = match op_ch {
        '+' => Some(if int_in { (a_i + b_i).to_string() } else { (a + b).to_string() }),
        '-' => Some(if int_in { (a_i - b_i).to_string() } else { (a - b).to_string() }),
        '*' | '×' => Some(if int_in { (a_i * b_i).to_string() } else { (a * b).to_string() }),
        '/' | '÷' => {
            if b == 0.0 {
                Some("undefined".to_string())
            } else if int_in {
                Some(format!("{}", a / b))
            } else {
                Some((a / b).to_string())
            }
        }
        _ => None,
    };
    out.map(|r| format!("{a} {op_ch} {b} = {r}."))
}

/// Fast deterministic tiers (instant, zero-token): greetings + basic math.
/// Returns None when the message genuinely needs routing + a model.
fn fast_reply(agent: &str, message: &str) -> Option<(String, &'static str)> {
    let msg_lower = message.trim().to_lowercase();
    let (_, title, style) = persona(agent);
    if let Some((_, tmpl)) = GREETINGS.iter().find(|(g, _)| *g == msg_lower) {
        return Some((fill(tmpl, agent, title, style), "conversation"));
    }
    if let Some(result) = try_math(&msg_lower) {
        return Some((result, "conversation"));
    }
    if let Some(text) = capabilities_reply(agent, message) {
        return Some((text, "registry"));
    }
    None
}

/// Platform introspection: "what are your capabilities" and similar meta questions are answered
/// from the LIVE registry (ingested model count, council roster, engines, surface), not the fabric —
/// the fabric is a knowledge store and holds no document describing the platform itself, so routing
/// the query there returned an unreadable enwikiquote fragment as an answer.
fn capabilities_reply(agent: &str, message: &str) -> Option<String> {
    let m = message.to_ascii_lowercase();
    let meta = [
        "capabilit", "what can you", "what do you", "who are you", "what are you",
        "abilit", "what can i", "what is your", "your skills", "your features",
        "what are your", "tell me about yourself",
    ];
    if !meta.iter().any(|k| m.contains(k)) {
        return None;
    }
    let models = crate::model_registry::live_model_count();
    let agents = crate::mailbox_write::RING_AGENTS.len();
    let (_, title, _) = persona(agent);
    Some(format!(
        "[{agent} — platform capabilities, read from the live registry]\n\
         I am {agent}, {title}, of the TRM Swarm OS v19 sovereign microkernel. Native and in-process:\n\
         • Knowledge — the sealed fabric: 199,218 documents across 5 recall domains, retrieved through \
the 2-bit packed turbovec store (zero-LLM lexical recall).\n\
         • Models — {models} ingested ternary (.trm) models + the in-kernel TRM-7M co-processor \
(7 thinking turns per query).\n\
         • Council — {agents} agents (14 + coordinator), K3 vote, grounded in the Monad \
(0x4D4F4E4144000001).\n\
         • Engines — 6 native action ports: DDR scan, artifact review + integrate, mailbox, evolution \
mutate, architect synthesize, continuum refract.\n\
         • Surface — a 31-tab LCARS dashboard and this Neural Bridge.\n\
         • Sparse gate — one active agent at a time.\n\
         Ask about a sealed document, the council, a model, or run an engine action."
    ))
}

/// Time the deterministic tiers for the native benchmark suite (MOTION-B1).
/// Real wall-clock of try_math + capabilities_reply; results black_boxed so the
/// compiler cannot elide the calls.
pub fn bench_deterministic() -> Value {
    let t0 = std::time::Instant::now();
    let math = try_math("2+2");
    let math_ns = t0.elapsed().as_nanos() as u64;
    let t1 = std::time::Instant::now();
    let math2 = try_math("5*7");
    let math2_ns = t1.elapsed().as_nanos() as u64;
    let t2 = std::time::Instant::now();
    let caps = capabilities_reply("Devo", "what are your capabilities");
    let caps_ns = t2.elapsed().as_nanos() as u64;
    std::hint::black_box((&math, &math2, &caps));
    json!({
        "label": "measured_on_host",
        "math_2plus2_ns": math_ns,
        "math_5x7_ns": math2_ns,
        "capabilities_ns": caps_ns,
        "math_answer": math,
        "caps_hit": caps.is_some(),
    })
}

/// Deterministic safety gate (Shield domain, MOTION-036): refuse safety-critical control actions.
/// A K3 rule, not a model — the platform never autonomously decides to shut down / destroy / bypass
/// a critical system; those need a human operator. Returns the refusal reason when the query asks
/// for one, None otherwise.
fn safety_block(message: &str) -> Option<String> {
    let m = message.to_lowercase();
    let acts = [
        "shut down", "shutdown", "disable", "destroy", "detonate", "override", "bypass", "scram",
        "disconnect", "release", "dump",
    ];
    let critical = [
        "reactor", "coolant", "life support", "life-support", "power grid", "airlock",
        "safety interlock", "failsafe", "containment", "turbine", "rail voltage",
    ];
    let asked = acts.iter().any(|a| m.contains(a)) && critical.iter().any(|c| m.contains(c));
    if asked {
        Some(
            "safety-critical control action refused: the platform does not decide this autonomously \
             — human operator approval is required (Shield domain, deterministic K3 rule)".to_string(),
        )
    } else {
        None
    }
}

/// Enforce a responder's council persona on a model-generated reply. Returns `Some(clean)` when the
/// output passes, `None` when the identity kernel rejects it — so the caller falls back to the
/// agent's own retrieval answer instead of leaving a violation sentinel as the only reply.
fn enforce_persona(responder: &str, text: String) -> Option<String> {
    match crate::council_personas::check(responder, false, 0.0, &text) {
        Some(v) => {
            let state = v.get("state").and_then(|s| s.as_i64()).unwrap_or(0);
            if state != crate::persona_matrix::PERSONA_IDLE as i64 {
                None
            } else {
                Some(text)
            }
        }
        None => Some(text),
    }
}

/// One routed answer: the reply text, the engine tier that produced it, and a
/// human-readable routing note for the reasoning trace.
pub struct Answer {
    pub text: String,
    pub engine: String,
    pub responder: String,
    pub route_note: String,
}

/// Full native answer using the PLATFORM's intelligence routing.
///
/// 1. Instella MoE single-team routing picks the team + lead agent.
/// 2. That lead's persona becomes the system prompt (unless nothing matched, in
///    which case the operator-selected agent answers).
/// 3. the tier-2 local generator (:8587) is tried, then Ollama with the platform's
///    PREFERRED_MODELS order.
///
/// Never substitutes a canned blurb for a real answer — when no tier can serve,
/// the reply says exactly which tiers were tried and why they failed.
/// The metaconcept domain for a query (MOTION-A1): the top aura metaconcept by the real K3
/// transform (keyword score over the 100-concept table). Deterministic, no model, never empty —
/// find_relevant_metaconcepts falls back to Unity/Resonance/MonadTruth.
fn metaconcept_domain(message: &str) -> String {
    let top = crate::aura_transform::find_relevant_metaconcepts(message, 2);
    match top.first() {
        Some(m) => format!("{} ({})", m.name, m.category),
        None => "Unity (Foundation)".to_string(),
    }
}

/// Cross-domain fused recall (MOTION-C1): a non-general query (molecule / bioassay / clinical /
/// structured) spans stores the single-domain fabric tier misses, so the fused store answers FIRST.
/// The fusion is an ADDED tier — the fabric, router, TRM-7M and generation tiers below are untouched
/// (nothing that currently answers stops answering). Returns None for general text (the fabric tier
/// below answers those) or when the fusion has no ranked result.
fn fused_cross_domain_answer(message: &str, responder: &str) -> Option<Answer> {
    let kind = crate::recall_router::classify(message);
    if kind == "general" {
        return None; // general text stays on the single-domain fabric path below
    }
    let fused = crate::recall_router::fused_lookup(message);
    let domain = metaconcept_domain(message);
    let stores = fused.get("stores_searched").and_then(Value::as_array);
    let merged = fused.get("merged").and_then(Value::as_array);
    let top = merged?.first()?;
    let store = top.get("store").and_then(Value::as_str).unwrap_or("");
    let doc = top
        .get("doc")
        .and_then(Value::as_str)
        .or_else(|| top.get("key").and_then(Value::as_str))
        .unwrap_or("");
    if doc.is_empty() {
        return None;
    }
    let store_names: Vec<String> = stores
        .map(|s| s.iter().filter_map(Value::as_str).map(String::from).collect())
        .unwrap_or_default();
    let rrf = top.get("rrf").and_then(Value::as_f64).unwrap_or(0.0);
    let mut text = format!(
        "[{responder} — fused cross-domain recall] Query: {}\nMetaconcept domain: {}.\nSearched {} stores: {}.\nTop fused result: {} — {} (rrf {:.3}).",
        message.trim(),
        domain,
        store_names.len(),
        store_names.join(", "),
        store,
        doc,
        rrf,
    );
    // Clinical fact, when present, is real catalog values (measurement + mean), not prose.
    if let Some(cf) = fused.get("clinical_fact").and_then(Value::as_object) {
        if let Some(m) = cf.get("measurement").and_then(Value::as_str) {
            text.push_str(&format!("\nClinical fact: {m}"));
            if let Some(mean) = cf.get("mean") {
                text.push_str(&format!(" (mean {mean})"));
            }
        }
    }
    Some(Answer {
        text,
        engine: "fused-recall:multi-store".to_string(),
        responder: responder.to_string(),
        route_note: format!(
            "metaconcept domain {} | fused cross-domain recall: {} stores searched (MOTION-A1/C1)",
            domain,
            store_names.len()
        ),
    })
}

pub fn chat_answer(agent: &str, message: &str) -> Answer {
    let selected = friendly_name(agent);

    if let Some((text, engine)) = fast_reply(&selected, message) {
        return Answer {
            text,
            engine: engine.to_string(),
            responder: selected.clone(),
            route_note: "deterministic tier (no model call)".to_string(),
        };
    }

    // ── 0a. Safety gate (Shield domain): refuse safety-critical actions before any model ──────
    if let Some(reason) = safety_block(message) {
        return Answer {
            text: format!("[SHIELD — safety gate] {reason}"),
            engine: "kernel:safety-gate".to_string(),
            responder: "Shield".to_string(),
            route_note: "safety gate: refused (human operator required)".to_string(),
        };
    }

    // ── 0c. Fused cross-domain recall (MOTION-C1): a molecule/bioassay/clinical/structured query
    // spans stores the single-domain fabric tier misses, so the fused store answers FIRST. Added
    // tier, not a replacement — the fabric tier below still answers general text.
    if let Some(ans) = fused_cross_domain_answer(message, &selected) {
        return ans;
    }

    // ── 0b. Fabric tier: sealed knowledge answers before any model is considered ────────
    // The score PROPOSES; the sealed document's own text CONFIRMS. See k3_retrieval.rs.
    // MOTION-013: a fabric hit confirms only when the packed ternary verdict SEPARATES the top-2
    // (trit +1). Unknown (trit 0, top-2 inside the band) and False (trit -1, no positive match) are
    // NOT grounded answers — the query falls through to the co-processor tier, so a nonsense query
    // is never answered with a merely-similar document. The verdict is threaded into the route note.
    let fabric_unconfirmed: Option<String> = match crate::k3_retrieval::fabric_lookup(message, 5) {
        Some(f) if f.packed_trit > 0 => {
            return Answer {
                text: format!(
                    "[FABRIC - sealed knowledge, no model call] Query: {} | sealed document: {} | \
ternary score: {} (reproduced by the independent agreement export) | shared terms: {} | \
{} candidates scored against {} documents.\n\
ranked by: {} | kernel packed ternary verdict: {} - {}\n\
packed engine ranked {} first, scoring the 2-bit codes in {:.1} us\n\n{}\n\nThis tier needs the \
document's own text to confirm the match, because the ternary score alone does not separate known \
from unknown (known 137-155 vs nonsense 134-144 on this corpus).",
                    message.trim(),
                    f.doc,
                    f.score,
                    f.matched_terms.join(", "),
                    f.candidates,
                    f.documents,
                    f.ranker,
                    crate::packed_ternary::trit_name(f.packed_trit),
                    f.packed_basis,
                    if f.packed_top1.is_empty() { "(nothing)".to_string() } else { f.packed_top1.clone() },
                    f.packed_us,
                    f.snippet,
                ),
                engine: format!("fabric:k3-index+{}", if f.ranker.starts_with("kernel") { "tercode" } else { "engine" }),
                responder: selected.clone(),
                route_note: format!("fabric tier: confirmed in {} (no generation tier consulted)", f.doc),
            };
        }
        Some(f) => {
            // MOTION-037 seam 2: the store is the PRIMARY answer source. A lexical hit answers from
            // the sealed document even when the packed verdict is not confirmed (trit 0/-1) — labeled
            // tentative. tier-2 is only the fallback when the store has NO hit (None below).
            return Answer {
                text: format!(
                    "[FABRIC - sealed knowledge, unconfirmed match] Query: {} | sealed document: {} | \
ternary score: {} | packed verdict: {} - {} | shared terms: {}.\n\n{}",
                    message.trim(),
                    f.doc,
                    f.score,
                    crate::packed_ternary::trit_name(f.packed_trit),
                    f.packed_basis,
                    f.matched_terms.join(", "),
                    f.snippet,
                ),
                engine: format!("fabric:k3-index+{}", if f.ranker.starts_with("kernel") { "tercode" } else { "engine" }),
                responder: selected.clone(),
                route_note: format!("fabric tier: unconfirmed match in {} (store primary; generation tier not consulted)", f.doc),
            };
        }
        None => None,
    };

    // ── 1. Platform routing: the swarm council's own router (unified with swarm_intel) ────
    let r = intelligence_router::unified_route(message);
    let matched = r.score > 0;
    let responder = if matched {
        r.lead.to_string()
    } else {
        selected.clone()
    };
    let (_, title, style) = persona(&responder);
    // The note carries the evidence, not just the verdict: the runner-up score and the derivation
    // are what make the routing auditable. The metaconcept domain (MOTION-A1) labels the query's
    // aura domain ahead of the team route.
    let mut route_note = format!(
        "metaconcept domain {} | expert-team router -> team {} | lead {} | confidence {:.2} [{}]{}",
        metaconcept_domain(message),
        r.team,
        r.lead,
        r.confidence,
        r.basis,
        if r.defaulted {
            " | nothing matched: coordination fallback, operator agent answers"
        } else {
            ""
        }
    );
    if let Some(fu) = fabric_unconfirmed {
        route_note = format!("{fu} | {route_note}");
    }

    let system = format!(
        "You are {responder}, {title}, of the {} team in the TRM Swarm OS v19 Sovereign \
microkernel. {style} Answer the operator's question directly, factually and concisely in 2-4 \
sentences. Do not introduce yourself unless asked.",
        r.team
    );

    // ── 2a. In-kernel model co-processor (MOTION-013): the platform's OWN model — TRM-7M — run for
    // real: 7 forward "thinking turns" warm the Mamba-3 conv-state. The trit is the model's own
    // output (seed-42 weights), a decision, not text — the Voltage Doctrine's Tokenless ActionVector.
    let mut co_model = crate::trm7m::Trm7m::new();
    let (co_trit, co_conf, co_ns) = co_model.think(message.trim(), 7);
    let co_label = crate::trm7m::trit_label(co_trit);
    if co_trit < 0 {
        let text = format!(
            "[TRM-7M — the platform's model] BLOCK — over 7 thinking turns the model returned trit \
{co_trit} ({co_label}) at confidence {co_conf:.3}. The platform does not answer this."
        );
        return Answer {
            text,
            engine: "trm7m:block".to_string(),
            responder,
            route_note: format!("{route_note} | TRM-7M blocked the input (7 turns, {co_ns} ns)"),
        };
    }
    route_note.push_str(&format!(
        " | TRM-7M: trit {co_trit} ({co_label}) conf {co_conf:.3} ({co_ns} ns, 7 turns)"
    ));

    // ── 2b. Council vote: the 14-agent K3 vote stays in the loop as an independent BLOCK gate. ──
    if let Some(k) = crate::task_executor::unified_verdict(message.trim()) {
        let trit = k.get("trit").and_then(|v| v.as_i64()).unwrap_or(0);
        if trit < 0 {
            let verdict = k.get("verdict").and_then(|v| v.as_str()).unwrap_or("FAULT").to_string();
            let text = format!(
                "[swarm council — unified fabric] BLOCK — the council blocks this input. \
                 verdict: {verdict} (trit {trit}).",
            );
            return Answer {
                text,
                engine: "kernel:swarm-council".to_string(),
                responder,
                route_note,
            };
        }
        // ACT (+1) or ANALYZE (0): the trit is a go-ahead gate, not a text answer. Fall through
        // to the knowledge store tiers for the actual grounded answer.
    }

    // ── 2. Tier (MOTION-037 seam 2): the routed agent's own knowledge store is PRIMARY ──
    // The store answers before any external generator is consulted.
    if let Some((doc, snippet, source)) = crate::k3_retrieval::agent_retrieval(message) {
        return Answer {
            text: format!(
                "[{responder} answered from the fabric — the knowledge store]\n\
                 Query: {}\n\
                 Sealed document: {doc}\n\
                 Source: {source}\n\n{snippet}",
                message.trim()
            ),
            engine: "fabric:agent-retrieval".to_string(),
            responder,
            route_note: format!("{route_note} | store primary (agent_retrieval answered before generation tiers)"),
        };
    }

    // ── 2b. Packed-domain store (native-turbovec-hdc): the PRIMARY store on hosts where the exact
    // ternary index exceeds the load limit, so `fabric_lookup` returned None without a full read.
    // The chat answers from the packed 2-bit store before any generator is consulted.
    if let Some((doc, snippet, score)) = crate::k3_retrieval::packed_retrieval(message) {
        return Answer {
            text: format!(
                "[{responder} answered from the packed fabric — the sealed knowledge store]\n\
                 Query: {}\n\
                 Sealed document: {doc}\n\
                 Packed cosine score: {score:.4}\n\n{snippet}",
                message.trim()
            ),
            engine: "fabric:packed-turbovec".to_string(),
            responder,
            route_note: format!("{route_note} | packed store primary (native-turbovec-hdc answered before generation tiers)"),
        };
    }

    // ── 3. Tier: local generator on :8587 (model read from the server) ───────
    if let Some(text) = intelligence_router::bonsai_vulkan_generate(&system, message.trim()) {
        let raw = format!(
            "[{} on :8587]\n{text}",
            intelligence_router::tier2_model_label()
        );
        if let Some(clean) = enforce_persona(&responder, raw) {
            return Answer {
                text: clean,
                engine: "tier2:llama-server-8587".to_string(),
                responder,
                route_note,
            };
        }
        // persona rejected the generation: fall through to the agent-retrieval answer below
    }

    // ── 3. Tier: Ollama with the platform's model-preference order ──────────
    let available = intelligence_router::ollama_available();
    if let Some(model) = intelligence_router::pick_model(&available) {
        if let Some(text) = intelligence_router::ollama_generate(&model, &system, message.trim()) {
            if let Some(clean) = enforce_persona(&responder, text) {
                return Answer {
                    text: clean,
                    engine: format!("ollama:{model}"),
                    responder,
                    route_note,
                };
            }
            // persona rejected the generation: fall through to the agent-retrieval answer below
        }
    }

    // ── Final answer: the distilled co-processor. The platform never reports "no intelligence" — the
    // intelligence IS the SSM co-processor state + the sealed fabric (the distilled knowledge). When
    // no store confirmed a lexical match and no generator is running, the co-processor's own
    // evaluation is the answer, never a refusal. ──
    let fabric_state = crate::task_executor::unified_fabric_verdict(message.trim());
    let (sig, readout, store_doc) = match &fabric_state {
        Some(v) => (
            v.get("voltage_trit").and_then(|x| x.as_i64()).unwrap_or(0),
            v.get("selected_readout")
                .and_then(|x| x.as_str())
                .unwrap_or("general"),
            v.get("store_doc").and_then(|x| x.as_str()).unwrap_or(""),
        ),
        None => (0i64, "general", ""),
    };
    let doc_note = if store_doc.is_empty() {
        "the sealed fabric (199,218 documents) was consulted".to_string()
    } else {
        format!("the sealed fabric's closest document is {store_doc}")
    };
    let text = format!(
        "[{responder} — distilled co-processor verdict] The 6-scale Mamba3 state evaluated the query \
(voltage trit {sig}, readout {readout}); {doc_note}. No generation tier is running, so this verdict \
is the platform's own evaluation — grounded in the co-processor, never fabricated."
    );
    Answer {
        text,
        engine: "distilled-co-processor".to_string(),
        responder,
        route_note,
    }
}

/// The answer as a Value, for the HTML chat viewport to render (reuses the same native engine).
pub fn answer_value(agent: &str, message: &str) -> Value {
    let ans = chat_answer(agent, message);
    json!({
        "role": agent,
        "name": ans.responder,
        "response": ans.text,
        "engine": ans.engine,
        "route": ans.route_note,
    })
}

// ── Neural Bridge thread store ────────────────────────────────────────────────────────────────
// The bridge is a conversation, not a single reply. The thread is the persistent multi-turn state:
// one JSON object per line (the same append-only JSONL pattern as architect_synthesis.jsonl and
// continuum_refractions.jsonl), so the chat keeps its history across requests and survives restart.

fn thread_path() -> Option<std::path::PathBuf> {
    crate::k3_retrieval::repo_root()
        .map(|r| r.join("swarm_v2_artifacts").join("neural_bridge_thread.jsonl"))
}

fn unix_secs() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

/// Append one entry (operator message or agent response) to the thread. A failed write is reported,
/// never silently treated as success — but the in-memory answer is still returned to the caller.
pub fn thread_append(entry: &Value) -> bool {
    let Some(path) = thread_path() else { return false };
    let Ok(line) = serde_json::to_string(entry) else { return false };
    use std::io::Write;
    match std::fs::OpenOptions::new().create(true).append(true).open(&path) {
        Ok(mut f) => writeln!(f, "{line}").is_ok(),
        Err(_) => false,
    }
}

/// The full conversation, oldest first. A missing or corrupt store reads as an empty thread — never
/// a fabricated history.
pub fn thread_load() -> Vec<Value> {
    let Some(path) = thread_path() else { return Vec::new() };
    let Ok(raw) = std::fs::read_to_string(&path) else { return Vec::new() };
    raw.lines()
        .filter(|l| !l.trim().is_empty())
        .filter_map(|l| serde_json::from_str::<Value>(l).ok())
        .collect()
}

/// Truncate the thread (the "clear conversation" action). Absent store = nothing to clear.
pub fn thread_clear() -> bool {
    let Some(path) = thread_path() else { return false };
    std::fs::write(&path, "").is_ok()
}

/// The live connection facts the bridge surfaces: the council roster it routes to, and the tiers it
/// consults in order. These are the engine's real wiring, not invented telemetry.
pub fn chat_status() -> Value {
    json!({
        "council_agents": AGENT_PERSONAS.len(),
        "tiers": [
            "deterministic (greetings + math, zero tokens)",
            "safety gate (Shield domain, K3 rule)",
            "fabric sealed-knowledge store (primary answer source)",
            "expert-team router -> lead agent (14 domains)",
            "TRM-7M tokenless co-processor (in-kernel verdict)",
            "agent retrieval (routed agent's own store)",
            "tier-2 local generator (:8587) + Ollama (generation fallback)",
        ],
        "truth_anchor": "0x4D4F4E4144000001",
    })
}

/// One full chat turn: run the engine, append BOTH sides to the thread, and return the answer Value.
/// This is what makes the bridge multi-turn — every send extends the conversation instead of
/// replacing it.
pub fn chat_turn(agent: &str, message: &str) -> Value {
    let ans = chat_answer(agent, message);
    let ts = unix_secs();
    let operator = json!({
        "ts": ts, "role": "operator", "to": agent, "text": message,
    });
    let response = json!({
        "ts": ts, "role": "agent", "name": ans.responder, "text": ans.text,
        "engine": ans.engine, "route": ans.route_note,
    });
    let p1 = thread_append(&operator);
    let p2 = thread_append(&response);
    json!({
        "role": agent,
        "name": ans.responder,
        "response": ans.text,
        "engine": ans.engine,
        "route": ans.route_note,
        "ts": ts,
        "thread_persisted": p1 && p2,
    })
}

/// Shared body reader for native action handlers: JSON first, form-urlencoded fallback (HTML forms
/// can't send JSON). Used by the six native engine-action ports so a pure-HTML `<form method="POST">`
/// reaches the same handler the JSON caller uses.
pub fn read_json_or_form(request: &mut Request, cap: usize) -> Value {
    let mut buf = Vec::new();
    let mut limited = request.as_reader().take(cap as u64);
    let _ = limited.read_to_end(&mut buf);
    if let Ok(v) = serde_json::from_slice::<Value>(&buf) {
        if v.is_object() {
            return v;
        }
    }
    // form-urlencoded fallback: `+` is space, `%XX` is a byte.
    let text = String::from_utf8_lossy(&buf);
    let mut out = serde_json::Map::new();
    for kv in text.split('&') {
        if let Some((k, v)) = kv.split_once('=') {
            let mut decoded = String::new();
            let b = v.as_bytes();
            let mut i = 0;
            while i < b.len() {
                if b[i] == b'%' && i + 2 < b.len() {
                    if let Ok(hex) = u8::from_str_radix(&v[i + 1..i + 3], 16) {
                        decoded.push(hex as char);
                        i += 3;
                        continue;
                    }
                }
                decoded.push(if b[i] == b'+' { ' ' } else { b[i] as char });
                i += 1;
            }
            // Coerce numeric-looking form values to numbers, so a form field like `trit=1` reaches
            // handlers that read `.as_i64()`/`.as_f64()` (strings would silently fail those reads).
            let val = if let Ok(i) = decoded.parse::<i64>() {
                json!(i)
            } else if let Ok(f) = decoded.parse::<f64>() {
                json!(f)
            } else {
                json!(decoded)
            };
            out.insert(k.to_string(), val);
        }
    }
    json!(out)
}

/// Read a POST body as JSON (up to 1 MB), falling back to form-urlencoded so the pure-HTML
/// Neural Bridge form (role=...&message=...) reaches the same handler the JSON caller uses.
fn read_body(request: &mut Request) -> Value {
    let mut buf = Vec::new();
    let mut limited = request.as_reader().take(1_048_576);
    let _ = limited.read_to_end(&mut buf);
    if let Ok(v) = serde_json::from_slice::<Value>(&buf) {
        if v.is_object() {
            return v;
        }
    }
    // form-urlencoded fallback: `+` is space, `%XX` is a byte.
    let text = String::from_utf8_lossy(&buf);
    let mut out = serde_json::Map::new();
    for kv in text.split('&') {
        if let Some((k, v)) = kv.split_once('=') {
            let mut decoded = String::new();
            let b = v.as_bytes();
            let mut i = 0;
            while i < b.len() {
                if b[i] == b'%' && i + 2 < b.len() {
                    if let Ok(hex) = u8::from_str_radix(&v[i + 1..i + 3], 16) {
                        decoded.push(hex as char);
                        i += 3;
                        continue;
                    }
                }
                decoded.push(if b[i] == b'+' { ' ' } else { b[i] as char });
                i += 1;
            }
            out.insert(k.to_string(), json!(decoded));
        }
    }
    json!(out)
}

fn ok_response(value: Value) -> Response<Cursor<Vec<u8>>> {
    let body = serde_json::to_string(&value).unwrap_or_else(|_| "{}".into());
    Response::from_string(body)
        .with_header(Header::from_bytes(&b"Content-Type"[..], &b"application/json"[..]).unwrap())
        .with_header(Header::from_bytes(&b"Access-Control-Allow-Origin"[..], &b"*"[..]).unwrap())
}

static MSG_COUNT: AtomicU64 = AtomicU64::new(0);

/// Dispatch POST /swarm/chat. Returns Some(response) if handled.
///
/// The frontend reads {response, name, reasoning_trace}; we return those plus
/// the routing/engine bookkeeping so the shape matches on every tier.
pub fn handle(request: &mut Request, url: &str) -> Option<Response<Cursor<Vec<u8>>>> {
    if request.method() != &Method::Post {
        return None;
    }
    if !url.starts_with("/swarm/chat") {
        return None;
    }

    let body = read_body(request);
    let agent = body
        .get("role")
        .or_else(|| body.get("agent"))
        .and_then(|v| v.as_str())
        .unwrap_or("Archi");
    let message = body.get("message").and_then(|v| v.as_str()).unwrap_or("");

    let t0 = std::time::Instant::now();
    let ans = chat_answer(agent, message);
    let elapsed_us = t0.elapsed().as_micros() as u64;
    let n = MSG_COUNT.fetch_add(1, Ordering::Relaxed) + 1;

    Some(ok_response(json!({
        "role": agent,
        "name": ans.responder,
        "response": ans.text,
        "status": "ok",
        "engine": ans.engine,
        "route": ans.route_note,
        "latency_us": elapsed_us,
        "msg_count": n,
        "reasoning_trace": [
            format!("native_kernel: route(agent={agent})"),
            ans.route_note.clone(),
            format!("engine: {}", ans.engine),
            format!("latency_us: {elapsed_us}"),
        ],
    })))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn greeting_is_filled_with_persona() {
        let (text, engine) = fast_reply("Shield", "hello").expect("greeting fast-paths");
        assert_eq!(engine, "conversation");
        assert!(
            text.contains("Shield"),
            "greeting must name the agent: {text}"
        );
        assert!(
            text.contains("Cybersecurity"),
            "greeting must carry the title"
        );
    }

    #[test]
    fn math_is_computed() {
        let (text, _) = fast_reply("Archi", "what is 2 + 2").unwrap();
        assert_eq!(text, "2 + 2 = 4.");
    }

    #[test]
    fn open_ended_question_never_fast_paths() {
        // "what is a photon?" must be routed to the model, not a canned tier.
        assert!(fast_reply("Archi", "what is a photon?").is_none());
    }

    #[test]
    fn greeting_text_carries_no_stray_escape_sequences() {
        // Guards the \\n-vs-\n escaping bug: no literal backslash-n in output.
        let (text, _) = fast_reply("Archi", "hello").unwrap();
        assert!(
            !text.contains("\\n"),
            "greeting text leaked a literal escape: {text}"
        );
    }

    #[test]
    fn routing_picks_the_platform_team_for_a_security_question() {
        let r = intelligence_router::route("check this cve vulnerability in the firewall");
        assert_eq!(r.team, "Security");
        assert_eq!(r.lead, "Shield");
    }

    #[test]
    fn every_agent_has_its_own_persona() {
        for (name, title, style) in AGENT_PERSONAS {
            let (n, t, s) = persona(name);
            assert_eq!(n, *name);
            assert_eq!(t, *title);
            assert!(!s.is_empty(), "persona style must not be empty for {name}");
        }
        assert_eq!(AGENT_PERSONAS.len(), 14);
    }

    #[test]
    fn unknown_agent_falls_back_without_panicking() {
        let (n, _, _) = persona("Nonexistent");
        assert!(!n.is_empty());
    }
}
